-- Teacher lesson plans for the Lesson library (0091).
--
-- Every generated lesson now comes with a lesson plan built from the same
-- content as its slides: a timed run-through with slide numbers, the
-- teacher script for each explanation, tasks, adaptations and homework.
-- Stored as an editable Word file and a PDF next to the deck. Plans are
-- regenerated by the "Build lesson decks" workflow; they are not versioned
-- like decks, and a teacher's edited deck keeps the generated plan.

alter table public.curriculum_lessons
  add column if not exists plan_pdf_path text,
  add column if not exists plan_docx_path text;

-- Allow Word documents in the lesson-decks bucket (plans are .docx).
update storage.buckets
   set allowed_mime_types = array[
     'application/pdf',
     'application/vnd.ms-powerpoint',
     'application/vnd.openxmlformats-officedocument.presentationml.presentation',
     'application/vnd.oasis.opendocument.presentation',
     'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
   ]
 where id = 'lesson-decks';
